// === CONFIGURATION ===
const config = {
  apify_token: 'YOUR_APIFY_API_TOKEN',
  groups_actor: 'apify/facebook-groups-scraper',

  // Local business / entrepreneur Facebook groups
  group_urls: [
    'https://www.facebook.com/groups/YOUR_LOCAL_BUSINESS_GROUP_1',
    'https://www.facebook.com/groups/YOUR_LOCAL_BUSINESS_GROUP_2',
    'https://www.facebook.com/groups/YOUR_LOCAL_ENTREPRENEUR_GROUP',
    'https://www.facebook.com/groups/YOUR_LOCAL_NETWORKING_GROUP'
  ],

  // Keywords that indicate someone is a small business owner
  business_owner_keywords: [
    'my business', 'my company', 'my shop', 'my store', 'my restaurant',
    'my salon', 'my clinic', 'small business', 'business owner',
    'entrepreneur', 'startup', 'founded', 'i own', 'we offer',
    'our services', 'our team', 'hiring', 'looking for clients',
    'just launched', 'grand opening', 'now open', 'new business',
    'side hustle', 'freelance', 'consulting', 'booking', 'appointments'
  ],

  // Keywords that suggest AI automation could help
  ai_opportunity_keywords: [
    'overwhelmed', 'too many', 'can\'t keep up', 'need help',
    'manual', 'paperwork', 'scheduling', 'bookkeeping',
    'social media', 'marketing', 'customer service', 'follow up',
    'follow-up', 'emails', 'invoicing', 'lead generation',
    'so busy', 'burned out', 'time consuming', 'repetitive',
    'looking for software', 'need a system', 'spreadsheet',
    'missed calls', 'late responses', 'losing customers',
    'need to automate', 'streamline', 'efficiency'
  ],

  // Business types most likely to benefit from AI automation
  high_value_business_types: [
    'restaurant', 'real estate', 'salon', 'barber', 'dental',
    'clinic', 'law firm', 'attorney', 'plumbing', 'hvac',
    'landscaping', 'cleaning', 'fitness', 'gym', 'coaching',
    'consulting', 'photography', 'wedding', 'event planning',
    'insurance', 'mortgage', 'roofing', 'contractor', 'auto shop',
    'mechanic', 'pet grooming', 'daycare', 'tutoring', 'accounting'
  ]
};

return { json: config };

// Process group posts to identify small business owners
// and score them for AI automation opportunity

const items = $input.all();
const config = $('Search Config').first().json;
const leads = [];

const businessKeywords = config.business_owner_keywords;
const aiKeywords = config.ai_opportunity_keywords;
const highValueTypes = config.high_value_business_types;

for (const item of items) {
  const data = item.json;
  if (!data || data.error) continue;

  const results = Array.isArray(data) ? data : [data];

  for (const post of results) {
    const text = (post.text || post.message || post.content || '').toLowerCase();
    const authorName = post.authorName || post.userName || post.author || '';
    const authorUrl = post.authorUrl || post.userProfileUrl || '';

    if (!text || text.length < 20) continue;

    // Check if post indicates business ownership
    const businessMatches = businessKeywords.filter(kw => text.includes(kw));
    if (businessMatches.length === 0) continue;

    // Score AI automation opportunity (0-100)
    let aiScore = 0;

    // Points for AI-related pain points mentioned
    const aiMatches = aiKeywords.filter(kw => text.includes(kw));
    aiScore += aiMatches.length * 15;

    // Points for being a high-value business type
    const typeMatches = highValueTypes.filter(type => text.includes(type));
    aiScore += typeMatches.length * 20;

    // Points for business ownership signals
    aiScore += businessMatches.length * 10;

    // Cap at 100
    aiScore = Math.min(aiScore, 100);

    // Only include leads with meaningful opportunity score
    if (aiScore < 15) continue;

    // Determine business type
    let businessType = 'Unknown';
    for (const type of highValueTypes) {
      if (text.includes(type)) {
        businessType = type.charAt(0).toUpperCase() + type.slice(1);
        break;
      }
    }

    // Extract potential business name (look for patterns)
    let businessName = '';
    const bizNamePatterns = [
      /(?:my (?:business|company|shop|store|salon|clinic)|i own)\s+(?:called|named)?\s*["']?([A-Z][\w\s&'-]+)/i,
      /(?:at|@)\s+([A-Z][\w\s&'-]+?)(?:\s+(?:in|on|and|we|is|are|the))/i,
      /([A-Z][\w\s&'-]+?)\s+(?:is hiring|is now|is looking|is open)/i
    ];
    const originalText = post.text || post.message || post.content || '';
    for (const pattern of bizNamePatterns) {
      const match = originalText.match(pattern);
      if (match) {
        businessName = match[1].trim();
        break;
      }
    }

    // Determine AI use cases based on keywords found
    const useCases = [];
    if (text.includes('scheduling') || text.includes('appointments') || text.includes('booking'))
      useCases.push('Automated scheduling & booking');
    if (text.includes('social media') || text.includes('marketing') || text.includes('content'))
      useCases.push('AI-powered social media & marketing');
    if (text.includes('customer service') || text.includes('missed calls') || text.includes('late responses'))
      useCases.push('AI customer service chatbot');
    if (text.includes('follow up') || text.includes('follow-up') || text.includes('lead'))
      useCases.push('Automated lead follow-up');
    if (text.includes('invoicing') || text.includes('bookkeeping') || text.includes('paperwork'))
      useCases.push('Automated invoicing & admin');
    if (text.includes('emails') || text.includes('email'))
      useCases.push('Email automation & sequences');
    if (text.includes('hiring') || text.includes('looking for'))
      useCases.push('AI-assisted recruiting');
    if (useCases.length === 0)
      useCases.push('General workflow automation');

    leads.push({
      json: {
        lead_id: 'BIZ-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6),
        business_name: businessName,
        owner_name: authorName,
        owner_profile_url: authorUrl,
        business_type: businessType,
        group_name: post.groupName || post.groupTitle || '',
        group_url: post.groupUrl || '',
        post_text: (post.text || post.message || post.content || '').substring(0, 2000),
        post_url: post.url || post.postUrl || '',
        ai_opportunity_score: aiScore,
        ai_use_cases: JSON.stringify(useCases),
        status: 'new',
        scraped_at: new Date().toISOString()
      }
    });
  }
}

// Sort by AI opportunity score (highest first)
leads.sort((a, b) => b.json.ai_opportunity_score - a.json.ai_opportunity_score);

return leads.length > 0 ? leads : [{ json: { _empty: true } }];

// Compare new leads against existing Google Sheet data
const existingRows = $input.all();
const classifiedLeads = $('Classify Business Leads').all().filter(item => !item.json._empty);

if (classifiedLeads.length === 0) {
  return [{ json: { _all_exist: true } }];
}

// Build set of existing owner profile URLs for dedup
const existingProfiles = new Set();
for (const row of existingRows) {
  if (row.json.owner_profile_url) {
    existingProfiles.add(row.json.owner_profile_url);
  }
}

// Return only leads not already in the sheet
const newOnly = classifiedLeads.filter(lead =>
  !existingProfiles.has(lead.json.owner_profile_url)
);

return newOnly.length > 0 ? newOnly : [{ json: { _all_exist: true } }];

// Generate personalized AI services outreach message
const lead = $input.item.json;

const ownerName = lead.owner_name || '';
const firstName = ownerName.split(' ')[0] || 'there';
const businessName = lead.business_name;
const businessType = lead.business_type;
const useCases = JSON.parse(lead.ai_use_cases || '[]');
const score = lead.ai_opportunity_score;

// Pick the top 2 most relevant use cases for the pitch
const topUseCases = useCases.slice(0, 2);

let useCaseText = '';
if (topUseCases.length > 0) {
  useCaseText = topUseCases.map(uc => `- ${uc}`).join('\n');
}

// Tailor the opening based on what we found in their post
let contextLine = '';
const postText = lead.post_text.toLowerCase();
if (postText.includes('overwhelmed') || postText.includes('burned out') || postText.includes('so busy')) {
  contextLine = 'I can tell you\'re putting in serious work, and I think there are some ways to free up your time.';
} else if (postText.includes('hiring') || postText.includes('looking for')) {
  contextLine = 'Before you hire, it might be worth seeing if automation could handle some of that workload first.';
} else if (postText.includes('missed calls') || postText.includes('losing customers')) {
  contextLine = 'I help businesses make sure no customer inquiry slips through the cracks.';
} else {
  contextLine = 'I help local businesses save time and grow by automating the repetitive stuff.';
}

const businessRef = businessName ? ` with ${businessName}` : (businessType !== 'Unknown' ? ` in the ${businessType} space` : '');

const message = `Hey ${firstName}! I saw your post in the group and it sounds like you're doing great things${businessRef}.

${contextLine}

I run Guardian Labs here in Lee's Summit - we build AI-powered automations for small businesses. Based on what you shared, a couple things that might help:

${useCaseText}

Would you be open to a quick 15-min chat to see if any of this could work for your business? No pitch, just trying to understand what would actually help. Happy to meet for coffee too!`;

return {
  json: {
    lead_id: lead.lead_id,
    owner_name: ownerName,
    business_name: businessName,
    ai_opportunity_score: score,
    outreach_type: 'ai_services',
    message_draft: message
  }
};
